// TH16 v1.00a Stage 3 mid-stage wave: three 32-enemy ECir00 spiral groups,
// each ECir00 firing short aimed volleys, then homing to the field center.
// Source: st03.ecl.txt MainSub05:1282-1325 (entry), ECir00:8-43,
// ECir00_at:45-107 (dependencies).
//
// Source -> target notes live next to the statements they justify.

const TIME_LIMIT: int = 1884;
const OPENING_BUFFER: int = 120;

// Source etSprite(0, 4, 6): TH16 type 4 = TH16_BALL, color 6.
const TH16_BALL: int = 416;
const BULLET_COLOR: int = 6;

const GROUP_SIZE: int = 32;   // $E/$F/$G = 32
const SPAWN_GAP: int = 10;    // wait(10) inside each group loop

// ----- ECir00_at: per-enemy firing task (source 45-107) -----
async sub ecir00_at() {
    var rank: int = global(GVAR_RANK);
    // 0048 !EN wait(10); 0050 !E wait(30): Easy stacks both waits.
    if rank <= 1 { wait(10); }
    if rank == 0 { wait(30); }

    // 0056-0063 layers, 0067-0075 first/last layer speed, 0080 loop count.
    var shots: int = 1;
    var layers: int = 1;
    var speed0: fx = 1fx;
    var speed1: fx = 1fx;
    var gap: int = 70;
    var jitter_amp: int = 182;   // !E 0.017453292f rad ~= 1deg
    if rank == 1 {
        shots = 2;
        jitter_amp = 1820;       // 0.17453292f rad ~= 10deg
    } else if rank == 2 {
        shots = 4;
        speed0 = 2fx;
        gap = 30;
        jitter_amp = 1820;
    } else if rank == 3 {
        shots = 20;
        layers = 2;
        speed0 = 2fx;
        speed1 = 1fx;
        gap = 10;
        jitter_amp = 1820;
    }
    for i in 0..shots {
        // 0082-0092 alpha = ANGLE_PLAYER + RANDF2 * amp, one draw per volley.
        // RANDF2 in [-1,1): r/32768 done as two exact power-of-two divisions.
        var u: fx = ((rand(65536) - 32768) as fx) / 32fx / 1024fx;
        var base: angle = atan2($player_y - $self_y, $player_x - $self_x)
                          + ((((jitter_amp as fx) * u) as int) as angle);
        for q in 0..layers {
            // 0066/0092 etAim(3) ring, 1 way: angle = alpha + q * 10deg.
            var a: angle = base + ((q * 1820) as angle);
            var sp: fx = speed0;
            if q == 1 { sp = speed1; }
            // 0077 etEx type 2 (ANIM) keeps its birth shift: position -= 4*velocity.
            var bx: fx = $self_x - 4fx * sp * cos(a);
            var by: fx = $self_y - 4fx * sp * sin(a);
            _ = fire(TH16_BALL, BULLET_COLOR, bx, by, sp, a, none, none);
        }
        wait(gap);   // 0103 wait([-1])
    }
}

// ----- ECir00: real enemy carrying the volley task (source 8-43) -----
async sub ecir00(body_x: fx, body_y: fx) {
    set_invuln(65535);
    // 0014 setHurtbox(24,24) -> r 12; 0015 setHitbox(16,16) -> r 8.
    set_hurtbox(12fx);
    set_hitbox(8fx);
    // 0025-0027 movePosRel(RANDF2*16) then REL eased back over 60 frames
    // (mode 1 = quadratic in); the scatter is folded into the spawn offset.
    move_to(60, body_x, body_y, EASE_QUAD_IN);
    wait(60);
    spawn ecir00_at();   // 0032 @ECir00_at() async
    wait(60);
    // 0034-0036 head to (0,191): speed 0 -> 3 over 120 frames (mode 0 = linear).
    var dir: angle = atan2(191fx - $self_y, 0fx - $self_x);
    move_vel(0, dir, 0fx, EASE_LINEAR);
    move_speed(120, 3fx, EASE_LINEAR);
    loop { wait(1000); }   // source 0037-0041: stay until recycled offscreen
}

// ----- MainSub05: 32 spawns, 10 frames apart (source 1282-1325) -----
sub ecir_group(step: angle) {
    var ang: angle = 90deg;   // 1285/1298/1311 %A = 1.570796f
    var radius: fx = 0fx;     // %B = 0.0f
    for i in 0..GROUP_SIZE {
        // 1290 circlePos: C = B*cos(A), D = B*sin(A), then +192 in y at 1291.
        var bx: fx = radius * cos(ang);
        var by: fx = radius * sin(ang) + 192fx;
        // 0025 movePosRel(%RANDF2 * 16, %RANDF2 * 16), x draw then y draw.
        var rx: fx = (((rand(65536) - 32768) as fx) / 32fx / 1024fx) * 16fx;
        var ry: fx = (((rand(65536) - 32768) as fx) / 32fx / 1024fx) * 16fx;
        // 1291 enmCreateF("ECir00", C, D+192, hps 70, score 1000, item 1);
        // no boss0 exists in the standalone card, so the F gate spawns.
        _ = spawn_enemy(bx + rx, by + ry, 70, 0, 1000, 0, ecir00(bx, by));
        ang = ang + step;      // 1292/1305/1318 +-0.349066f
        radius = radius + 5fx; // 1293/1306/1319 +5.0f
        wait(SPAWN_GAP);       // 1294/1307/1320
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    ecir_group(-20deg);   // 1289-1296 first spiral (A decreasing)
    wait(20);             // 1297
    ecir_group(20deg);    // 1302-1309 second spiral (A increasing)
    wait(160);            // 1310
    ecir_group(-20deg);   // 1315-1322 third spiral
    wait(160);            // 1323
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
